16	
17		if create.ExpiresTs != nil {
18			fields = append(fields, "`expires_ts`")
19			placeholders = append(placeholders, "?")
20			args = append(args, *create.ExpiresTs)
21		}
22	
23		stmt := "INSERT INTO `memo_share` (" + strings.Join(fields, ", ") + ") VALUES (" + strings.Join(placeholders, ", ") + ") RETURNING `id`, `created_ts`"
24		if err := d.db.QueryRowContext(ctx, stmt, args...).Scan(
25			&create.ID,
26			&create.CreatedTs,
27		); err != nil {
28			return nil, err
29		}
30		return create, nil
